00000005","category":"A classificar","event_date":"2001-01-15","source_ref":"11111111-1111-4111-8111-000000000005","beneficiary":null,"description":"SYNTHETIC PURCHASE 5","raw_category":"A classificar","source_table":"lts_open_finance_staging","coverage_mode":"synthetic","property_code":null,"purchase_date":null,"raw_reference":"SYNTHETIC PURCHASE 5","account_source":"SYNTHETIC ACCOUNT","identity_status":"pending","competence_month":"2001-01-01","management_group":"A classificar","transaction_date":"2001-01-15","property_component":null,"management_subgroup":"A classificar"},"evidence":"SYNTHETIC ONLY","installment_key_expected":null,"key_source_ids_expected":[]}]$targets$::jsonb;
