 SELECT u,'lts_open_finance_staging',j.value->>'source_ref',j.value->>'beneficiary',NULL,j.value->>'category','documented_exact_occurrence_restore_20261016:'||op,transaction_timestamp() FROM jsonb_array_elements(targets) AS j(value)
;
 GET DIAGNOSTICS n=ROW_COUNT; IF n<>5 THEN RAISE EXCEPTION 'atomic insert cardinality failed: %',n; END IF;
